<script setup lang="ts">
import { CheckCircle2, ClipboardList, Link2, RefreshCw, Search, Settings2, Wifi, X } from '@lucide/vue';
const config = useRuntimeConfig(); const route = useRoute();
const { token } = useWorkspaceSession(); const busy = ref(false); const notice = ref('');
const { openContextMenu, copyText } = useContextMenu();
const orders = ref<any[]>([]); const integrations = ref<any[]>([]); const search = ref(''); const channel = ref(''); const statusFilter = ref(''); const selected = ref<any>(null);
const channels = [{ id: 'WILDBERRIES', name: 'Wildberries', color: '#cb11ab' }, { id: 'OZON', name: 'Ozon', color: '#005bff' }, { id: 'YANDEX_MARKET', name: 'Яндекс Маркет', color: '#ffcc00' }, { id: 'MEGAMARKET', name: 'Мегамаркет', color: '#e6332a' }];
const statuses = [{ id: 'NEW', label: 'Новые' }, { id: 'CONFIRMED', label: 'Подтверждены' }, { id: 'ASSEMBLING', label: 'Сборка' }, { id: 'SHIPPED', label: 'Отправлены' }, { id: 'DELIVERED', label: 'Доставлены' }, { id: 'CANCELLED', label: 'Отменены' }, { id: 'RETURNED', label: 'Возвраты' }];
const section = computed(() => String(route.query.section || 'dashboard'));
const filteredOrders = computed(() => orders.value.filter((order) => (!channel.value || order.channel === channel.value) && (!statusFilter.value || order.status === statusFilter.value) && (!search.value || `${order.externalId} ${order.buyerName || ''} ${order.channel}`.toLowerCase().includes(search.value.toLowerCase()))));
const stats = computed(() => ({ total: orders.value.length, new: orders.value.filter(o => o.status === 'NEW').length, assembling: orders.value.filter(o => o.status === 'ASSEMBLING').length, revenue: orders.value.reduce((sum, o) => sum + Number(o.totalAmount || 0), 0) }));
function integration(id: string) { return integrations.value.find(i => i.channel === id) || { channel: id, shopName: '', isActive: false }; }
function labelStatus(value: string) { return statuses.find(s => s.id === value)?.label || value; }
function labelChannel(value: string) { return channels.find(c => c.id === value)?.name || value; }
async function load() { if (!token.value) return; busy.value = true; try { const headers = { Authorization: `Bearer ${token.value}` }; [orders.value, integrations.value] = await Promise.all([$fetch<any[]>('/marketplaces/orders', { baseURL: config.public.apiBase, headers }), $fetch<any[]>('/marketplaces/integrations', { baseURL: config.public.apiBase, headers })]); } finally { busy.value = false; } }
async function updateStatus(order: any, value: string) { await $fetch(`/marketplaces/orders/${order.id}`, { baseURL: config.public.apiBase, method: 'PATCH', headers: { Authorization: `Bearer ${token.value}` }, body: { status: value } }); order.status = value; notice.value = 'Статус заказа обновлён'; setTimeout(() => notice.value = '', 2200); }
async function saveIntegration(item: any) { await $fetch('/marketplaces/integrations', { baseURL: config.public.apiBase, method: 'POST', headers: { Authorization: `Bearer ${token.value}` }, body: { channel: item.channel, shopName: item.shopName || `${labelChannel(item.channel)} магазин`, isActive: item.isActive, credentials: { configuredFrom: 'marketplace-console' } } }); await load(); notice.value = 'Интеграция сохранена'; setTimeout(() => notice.value = '', 2200); }
async function testIntegration(id: string) { const result = await $fetch<any>(`/marketplaces/integrations/${id}/test`, { baseURL: config.public.apiBase, method: 'POST', headers: { Authorization: `Bearer ${token.value}` } }); notice.value = result.message || 'Подключение работает'; setTimeout(() => notice.value = '', 3000); await load(); }
function orderMenu(event:MouseEvent,order:any){const index=statuses.findIndex(item=>item.id===order.status);const next=statuses[index+1];openContextMenu(event,order.externalId,[{label:'Открыть карточку',icon:'open',action:()=>selected.value=order},{label:'Копировать номер площадки',icon:'copy',action:()=>copyText(order.externalId,'Номер заказа скопирован')},{label:'Копировать номер OMS',icon:'copy',action:()=>copyText(order.orderNumber,'Номер OMS скопирован')},...(next?[{label:`Статус: ${next.label}`,icon:'status' as const,separator:true,action:()=>updateStatus(order,next.id)}]:[])],labelChannel(order.channel));}
function integrationMenu(event:MouseEvent,item:any){const current=integration(item.id);openContextMenu(event,item.name,[{label:'Проверить подключение',icon:'refresh',action:()=>testIntegration(item.id)},{label:'Сохранить настройки',icon:'edit',action:()=>saveIntegration(current)},{label:'Копировать код канала',icon:'copy',separator:true,action:()=>copyText(item.id,'Код канала скопирован')}],current.isActive?'Подключён':'Не подключён');}
onMounted(load);
</script>
<template>
  <main class="marketplace-page">
    <template>
      <header class="mp-header"><div><p class="kicker">MARKETPLACE OPERATIONS</p><h1>Каналы продаж</h1><p class="subtitle">Контроль заказов и подключений в реальном времени</p></div><div class="header-actions"><button @click="load"><RefreshCw :size="16" :class="{spin: busy}" /> Обновить</button></div></header>
      <div class="mp-body"><nav class="tabs"><NuxtLink to="/crm-marketplaces?section=dashboard" :class="{active: section === 'dashboard'}">Обзор</NuxtLink><NuxtLink to="/crm-marketplaces?section=orders" :class="{active: section === 'orders'}"><ClipboardList :size="15" /> Заказы <b>{{ stats.total }}</b></NuxtLink><NuxtLink to="/crm-marketplaces?section=integrations" :class="{active: section === 'integrations'}"><Link2 :size="15" /> Интеграции</NuxtLink><NuxtLink to="/crm-marketplaces?section=settings" :class="{active: section === 'settings'}"><Settings2 :size="15" /> Настройки</NuxtLink></nav>
        <section v-if="section === 'dashboard'" class="dashboard-view"><div class="kpi-grid"><article><span>Всего заказов</span><strong>{{ stats.total }}</strong><small>за всё время</small></article><article><span>Новые</span><strong class="coral">{{ stats.new }}</strong><small>требуют внимания</small></article><article><span>В сборке</span><strong>{{ stats.assembling }}</strong><small>на складе</small></article><article><span>Оборот заказов</span><strong>{{ stats.revenue.toLocaleString('ru-RU') }} ₽</strong><small>по загруженным заказам</small></article></div><div class="dashboard-grid"><article class="panel channel-overview"><div class="panel-head"><div><p class="eyebrow">ПОДКЛЮЧЕНИЯ</p><h2>Каналы продаж</h2></div><NuxtLink to="/crm-marketplaces?section=integrations">Настроить</NuxtLink></div><div v-for="item in channels" :key="item.id" class="channel-line"><i :style="{background:item.color}"></i><strong>{{ item.name }}</strong><span>{{ integration(item.id).isActive ? 'Подключён' : 'Не подключён' }}</span><CheckCircle2 v-if="integration(item.id).isActive" :size="16" class="ok" /></div></article><article class="panel attention"><div class="panel-head"><div><p class="eyebrow">ОПЕРАЦИОННАЯ ЛЕНТА</p><h2>Последние заказы</h2></div><NuxtLink to="/crm-marketplaces?section=orders">Все заказы</NuxtLink></div><div v-for="order in orders.slice(0,5)" :key="order.id" class="compact-order"><div><strong>{{ order.externalId }}</strong><small>{{ labelChannel(order.channel) }} · {{ order.buyerName || 'Покупатель не указан' }}</small></div><span :class="`status status-${order.status.toLowerCase()}`">{{ labelStatus(order.status) }}</span></div><p v-if="!orders.length" class="empty">Заказов пока нет</p></article></div></section>
        <section v-else-if="section === 'orders'" class="panel orders-panel"><div class="panel-head"><div><p class="eyebrow">ОПЕРАЦИОННАЯ ЛЕНТА</p><h2>Заказы маркетплейсов</h2><p class="muted">Управляйте статусами и быстро находите нужный заказ.</p></div></div><div class="filters"><label class="search"><Search :size="16" /><input v-model="search" placeholder="Поиск по номеру или покупателю" /></label><select v-model="channel"><option value="">Все каналы</option><option v-for="item in channels" :key="item.id" :value="item.id">{{ item.name }}</option></select><select v-model="statusFilter"><option value="">Все статусы</option><option v-for="item in statuses" :key="item.id" :value="item.id">{{ item.label }}</option></select><button v-if="search || channel || statusFilter" class="clear" @click="search='';channel='';statusFilter=''">Сбросить</button></div><div class="table-wrap"><div class="order-row table-head"><span>Заказ</span><span>Канал</span><span>Покупатель</span><span>Сумма</span><span>Статус</span><span>Дата</span></div><div v-for="order in filteredOrders" :key="order.id" class="order-row clickable" @click="selected=order" @contextmenu.prevent="orderMenu($event,order)"><div><strong>{{ order.externalId }}</strong><small>{{ order.trackingNumber || 'Трек-номер не указан' }}</small></div><span>{{ labelChannel(order.channel) }}</span><span>{{ order.buyerName || 'Не указан' }}</span><strong>{{ Number(order.totalAmount || 0).toLocaleString('ru-RU') }} ₽</strong><select :value="order.status" @click.stop @change="updateStatus(order, ($event.target as HTMLSelectElement).value)"><option v-for="item in statuses" :key="item.id" :value="item.id">{{ item.label }}</option></select><span>{{ new Date(order.createdAt).toLocaleDateString('ru-RU') }}</span></div><p v-if="!filteredOrders.length" class="empty">По выбранным фильтрам заказов не найдено</p></div></section>
        <section v-else class="integrations-view"><div class="section-intro"><div><p class="eyebrow">ПОДКЛЮЧЕНИЯ</p><h2>Интеграции каналов</h2><p>Настройте магазины и проверьте связь с внешними площадками.</p></div></div><div class="integration-grid"><article v-for="item in channels" :key="item.id" class="integration-card" @contextmenu.prevent="integrationMenu($event,item)"><div class="integration-top"><i :style="{background:item.color}"></i><div><h3>{{ item.name }}</h3><span :class="{connected:integration(item.id).isActive}">{{ integration(item.id).isActive ? 'Подключён' : 'Не подключён' }}</span></div><CheckCircle2 v-if="integration(item.id).isActive" :size="18" class="ok" /></div><label>Название кабинета<input v-model="integration(item.id).shopName" :placeholder="`${item.name} магазин`" /></label><div class="card-actions"><button class="primary" @click="saveIntegration(integration(item.id))">Сохранить</button><button @click="testIntegration(item.id)"><Wifi :size="15" /> Проверить связь</button></div></article></div></section>
      </div>
    </template>
    <aside v-if="selected" class="drawer-backdrop" @click.self="selected=null"><div class="drawer"><button class="close" @click="selected=null"><X :size="18" /></button><p class="eyebrow">ЗАКАЗ МАРКЕТПЛЕЙСА</p><h2>{{ selected.externalId }}</h2><div class="drawer-status">{{ labelStatus(selected.status) }}</div><dl><dt>Номер в системе</dt><dd>{{ selected.orderNumber }}</dd><dt>Канал</dt><dd>{{ labelChannel(selected.channel) }}</dd><dt>Покупатель</dt><dd>{{ selected.buyerName || 'Не указан' }}</dd><dt>Сумма</dt><dd>{{ Number(selected.totalAmount || 0).toLocaleString('ru-RU') }} ₽</dd><dt>Создан</dt><dd>{{ new Date(selected.createdAt).toLocaleString('ru-RU') }}</dd></dl></div></aside><div v-if="notice" class="toast">{{ notice }}</div>
  </main>
</template>
<style scoped>
.marketplace-page{min-height:100vh;background:#f4f5f7;color:#1d1e22;font-family:var(--sb-font)}.mp-header{background:#fff;border-bottom:1px solid #e3e5e8;padding:30px 5%;display:flex;align-items:flex-end;justify-content:space-between}.kicker,.eyebrow{font-size:10px;letter-spacing:.16em;color:#f15b49;margin:0 0 8px}.mp-header h1{font-size:32px;margin:0;font-weight:600}.subtitle,.muted{color:#858991;font-size:12px;margin:8px 0 0}.header-actions button{height:40px;padding:0 15px;border:1px solid #dfe1e5;background:#fff;display:flex;gap:8px;align-items:center}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.mp-body{max-width:1240px;margin:0 auto;padding:24px 5%}.tabs{display:flex;gap:5px;border-bottom:1px solid #dedfe3;margin-bottom:24px}.tabs a{padding:12px 15px;display:flex;gap:7px;align-items:center;color:#7b7e86;text-decoration:none;font-size:12px;border-bottom:2px solid transparent}.tabs a.active{color:#1d1e22;border-color:#f15b49}.tabs b{font-size:10px;background:#f0f1f3;border-radius:10px;padding:2px 6px}.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.kpi-grid article,.panel,.integration-card{background:#fff;border:1px solid #e3e5e8}.kpi-grid article{padding:22px;display:grid;gap:8px}.kpi-grid span,.kpi-grid small{color:#858991;font-size:11px}.kpi-grid strong{font-size:27px;font-weight:500}.kpi-grid strong.coral{color:#f15b49}.dashboard-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.panel{padding:24px}.panel-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.panel-head h2,.section-intro h2{font-size:20px;margin:0}.panel-head a{color:#f15b49;font-size:11px;text-decoration:none}.channel-line,.compact-order{display:flex;align-items:center;gap:11px;min-height:52px;border-bottom:1px solid #eff0f2;font-size:12px}.channel-line i,.integration-top i{width:10px;height:10px;border-radius:50%;display:block}.channel-line span{margin-left:auto;color:#858991;font-size:11px}.ok{color:#2c9b69;margin-left:5px}.compact-order div{display:grid;gap:4px;flex:1}.compact-order small{font-size:10px;color:#858991}.status{font-size:10px;padding:5px 8px;background:#f0f1f3}.status-new{color:#c35342;background:#fff0ed}.status-delivered{color:#27865b;background:#eaf8f0}.status-cancelled,.status-returned{color:#8b5d5d;background:#f5eded}.status-assembling,.status-shipped,.status-confirmed{color:#536e9d;background:#edf3ff}.orders-panel{padding:0}.orders-panel>.panel-head{padding:24px 24px 0}.filters{display:flex;gap:8px;padding:18px 24px;border-top:1px solid #eff0f2;border-bottom:1px solid #eff0f2}.search{height:36px;display:flex;align-items:center;gap:8px;border:1px solid #dfe1e5;padding:0 10px;flex:1;color:#858991}.search input{border:0;outline:0;width:100%;font-size:12px}.filters select{height:36px;border:1px solid #dfe1e5;background:#fff;padding:0 10px;color:#4c4e54}.clear{border:0;background:transparent;color:#f15b49;font-size:11px}.table-wrap{overflow:auto}.order-row{display:grid;grid-template-columns:1.25fr 1fr 1.3fr 1fr 1.1fr .9fr;gap:14px;align-items:center;padding:14px 24px;border-bottom:1px solid #eff0f2;min-width:850px;font-size:12px}.order-row div{display:grid;gap:4px}.order-row small{font-size:10px;color:#858991}.table-head{font-size:10px;color:#858991;text-transform:uppercase;min-height:44px}.clickable{cursor:pointer}.clickable:hover{background:#fafafa}.order-row select{height:30px;border:1px solid #dfe1e5;background:#fff;font-size:11px}.empty{text-align:center;padding:35px;color:#858991;font-size:12px}.section-intro{margin-bottom:22px}.integration-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.integration-card{padding:24px}.integration-top{display:flex;align-items:center;gap:11px;margin-bottom:22px}.integration-top div{display:grid;gap:4px}.integration-top h3{margin:0;font-size:17px}.integration-top span{font-size:11px;color:#858991}.integration-top span.connected{color:#2c9b69}.integration-top .ok{margin-left:auto}.integration-card label{font-size:11px;color:#858991;display:grid;gap:7px}.integration-card input{height:38px;border:1px solid #dfe1e5;padding:0 10px}.card-actions{display:flex;gap:8px;margin-top:16px}.card-actions button{height:34px;border:1px solid #dfe1e5;background:#fff;padding:0 11px;font-size:11px;display:flex;gap:6px;align-items:center}.card-actions button.primary{background:#1d1e22;color:#fff;border-color:#1d1e22}.drawer-backdrop{position:fixed;inset:0;background:#0004;z-index:200}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(430px,90vw);background:#fff;padding:38px;box-sizing:border-box}.drawer .close{position:absolute;right:20px;top:20px;background:none;border:0}.drawer h2{font-size:28px;margin:0 0 15px}.drawer-status{display:inline-block;padding:7px 10px;background:#edf3ff;font-size:11px}.drawer dl{margin-top:30px;display:grid;grid-template-columns:1fr 1fr;gap:16px;border-top:1px solid #ececef;padding-top:20px}.drawer dt{color:#858991;font-size:11px}.drawer dd{margin:0;font-size:12px}.toast{position:fixed;right:24px;bottom:24px;background:#1d1e22;color:#fff;padding:13px 18px;font-size:12px;z-index:300}.mp-login{min-height:100vh;display:grid;place-items:center}.mp-login form{width:min(430px,90vw);padding:40px;background:#fff;border:1px solid #e3e5e8;display:grid;gap:14px}.mp-login h1{font-size:32px;margin:0}.mp-login p:not(.kicker){font-size:13px;line-height:1.6;color:#858991}.mp-login input{height:44px;border:1px solid #dfe1e5;padding:0 12px}.mp-login button{height:44px;background:#1d1e22;color:#fff;border:0}.mp-login span{color:#f15b49;font-size:12px}@media(max-width:900px){.kpi-grid{grid-template-columns:repeat(2,1fr)}.dashboard-grid,.integration-grid{grid-template-columns:1fr}.filters{flex-wrap:wrap}.search{flex-basis:100%}}@media(max-width:600px){.mp-header{align-items:flex-start;flex-direction:column;gap:18px}.tabs{overflow:auto}.mp-body{padding:20px 16px}}
</style>
